CREATE TABLE classroom_topics(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),classroom_id UUID NOT NULL REFERENCES classrooms(id) ON DELETE CASCADE,title TEXT NOT NULL CHECK(char_length(title) BETWEEN 1 AND 80),created_by UUID REFERENCES users(id) ON DELETE SET NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(id,classroom_id));
CREATE UNIQUE INDEX classroom_topic_title_unique ON classroom_topics(classroom_id,lower(title));
CREATE TABLE classroom_topic_resources(classroom_id UUID NOT NULL REFERENCES classrooms(id) ON DELETE CASCADE,topic_id UUID NOT NULL,resource_kind TEXT NOT NULL CHECK(resource_kind IN ('assignment','material')),resource_id UUID NOT NULL,PRIMARY KEY(resource_kind,resource_id),FOREIGN KEY(topic_id,classroom_id) REFERENCES classroom_topics(id,classroom_id) ON DELETE CASCADE);
